cypress_script:
describe('Checkout Overview and Totals', () => {
  it('should display the checkout overview with correct totals', () => {
    cy.visit('https://www.saucedemo.com/checkout-step-two.html');
    cy.get('[data-test="primary-header"]').should('be.visible');
    cy.get('[data-test="secondary-header"]').should('contain.text', 'Checkout: Overview');
    cy.get('[data-test="payment-info-label"]').should('contain.text', 'Payment Information:');
    cy.get('[data-test="payment-info-value"]').should('contain.text', 'SauceCard #31337');
    cy.get('[data-test="shipping-info-label"]').should('contain.text', 'Shipping Information:');
    cy.get('[data-test="shipping-info-value"]').should('contain.text', 'Free Pony Express Delivery!');
    cy.get('[data-test="total-info-label"]').should('contain.text', 'Price Total');
    cy.get('[data-test="subtotal-label"]').should('contain.text', 'Item total: $0');
    cy.get('[data-test="tax-label"]').should('contain.text', 'Tax: $0.00');
    cy.get('[data-test="total-label"]').should('contain.text', 'Total: $0.00');
  });

  it('should allow the user to cancel the checkout process', () => {
    cy.visit('https://www.saucedemo.com/checkout-step-two.html');
    cy.get('[data-test="cancel"]').click();
    cy.url().should('eq', 'https://www.saucedemo.com/');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Checkout Overview and Totals', () => {
  test('should display the checkout overview with correct totals', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/checkout-step-two.html');
    await expect(page.locator('[data-test="primary-header"]')).toBeVisible();
    await expect(page.locator('[data-test="secondary-header"]').textContent()).toContain('Checkout: Overview');
    await expect(page.locator('[data-test="payment-info-label"]').textContent()).toContain('Payment Information:');
    await expect(page.locator('[data-test="payment-info-value"]').textContent()).toContain('SauceCard #31337');
    await expect(page.locator('[data-test="shipping-info-label"]').textContent()).toContain('Shipping Information:');
    await expect(page.locator('[data-test="shipping-info-value"]').textContent()).toContain('Free Pony Express Delivery!');
    await expect(page.locator('[data-test="total-info-label"]').textContent()).toContain('Price Total');
    await expect(page.locator('[data-test="subtotal-label"]').textContent()).toContain('Item total: $0');
    await expect(page.locator('[data-test="tax-label"]').textContent()).toContain('Tax: $0.00');
    await expect(page.locator('[data-test="total-label"]').textContent()).toContain('Total: $0.00');
  });

  test('should allow the user to cancel the checkout process', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/checkout-step-two.html');
    await page.click('[data-test="cancel"]');
    await expect(page).toHaveURL('https://www.saucedemo.com/');
  });
});
